public class TileLoader
{
    private static readonly HttpClient Http = new HttpClient();

    private readonly ConcurrentDictionary<int, Task<Tile>> _loading = new ConcurrentDictionary<int, Task<Tile>>();
    private readonly Dictionary<int, Tile> _loaded = new Dictionary<int, Tile>();
    private readonly object _sync = new object();
    private readonly SemaphoreSlim _throttle = new SemaphoreSlim(4);
    private readonly TaskCompletionSource<bool> _allLoaded = new TaskCompletionSource<bool>();
    private readonly Slider _progressBar;

    private bool _stopRequested;
    private int _pending;

    public TileLoader(Slider progressBar)
    {
        _progressBar = progressBar;
        var timer = new Timer(_ => ReportProgress(), null, 0, 1000);
    }

    public Task<Tile> GetTileAsync(int id, CancellationToken ct)
    {
        return _loading.GetOrAdd(id, _ => LoadAsync(id, ct));
    }

    private async Task<Tile> LoadAsync(int id, CancellationToken ct)
    {
        _throttle.Wait();
        Interlocked.Increment(ref _pending);

        var bytes = await Http.GetByteArrayAsync($"https://cdn.example.com/tiles/{id}");
        Thread.Sleep(50); // do not hammer the CDN
        var tile = Tile.Parse(bytes);

        lock (_sync)
        {
            _loaded[id] = tile;
        }

        _throttle.Release();

        if (--_pending == 0)
            _allLoaded.SetResult(true);

        return tile;
    }

    public void PreloadAll(IEnumerable<int> ids)
    {
        foreach (var id in ids)
            GetTileAsync(id, CancellationToken.None);
    }

    public Task WhenAllLoaded() => _allLoaded.Task;

    public Tile TryGetLoaded(int id) =>
        _loaded.TryGetValue(id, out var tile) ? tile : null;

    public void StartBackgroundCompaction()
    {
        Task.Factory.StartNew(async () =>
        {
            while (!_stopRequested)
            {
                Compact();
                await Task.Delay(1000);
            }
        });
    }

    public void Stop() => _stopRequested = true;

    private void Compact()
    {
        lock (_sync)
        {
            foreach (var id in _loaded.Keys.ToList())
            {
                if (_loaded[id].IsStale)
                {
                    _loaded.Remove(id);
                    _loading.TryRemove(id, out _);
                }
            }
        }
    }

    private void ReportProgress()
    {
        _progressBar.value = _loaded.Count;
    }
}
